UPDATE lessons SET title='Year 4, Week 23, Lesson 1: Relationships and character change', data=json_patch(data,'{"child_mission":"Relationships and character change are shown through actions, dialogue and responses over time; readers track how one character affects another.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhat evidence shows change if a character first hides and later asks for help?\n\nFEEDBACK\nCompare early hiding with later asking; quote both moments.\n\nCHECK\nSaying a character \"got nicer\" without evidence is unsupported.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nChart one relationship across a text: early behaviour, later behaviour and a quoted turning point. Explain the change in four sentences.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Relationships and character change are shown through actions, dialogue and responses over time; readers track how one character affects another.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-RECOM-01","EN2-UARL-01"],"parent_notes":"Parent: Marking guidance for the independent task: Chart one relationship across a text: early behaviour, later behaviour and a quoted turning point. Explain the change in four sentences. Accept equivalent original responses that show the same skill.\n\nParent: Wri